def attempt(label)
  result = yield
  puts "#{label}: #{result.inspect}"
rescue WebAuthn::Error => e
  puts "#{label}: #{e.class}: #{e.message}"
rescue RuntimeError => e
  puts "#{label}: #{e.class}: #{e.message}"
end

